async def compute_score_batch(self, data: DataProto) -> list[dict]:
    tasks = []
    for i in range(len(data)):
        tasks.append(asyncio.create_task(self.compute_score(data[i : i + 1])))
    outputs = await asyncio.gather(*tasks)
    return outputs

async def compute_score(self, input_data) -> dict:
    """Compute reward score.

    Supports verl-native `DataProto` inputs, and (for DisRM only) DataProto-less inputs:
    - `str`: already-prepared classifier prompt
    - `list[dict]`: chat messages to be templated by `reward_model_tokenizer`
    """
    # verl-native path.
    if isinstance(input_data, DataProto):
        data = input_data
        assert len(data) == 1, "RewardLoopWorker only support single data item"
        if self.config.custom_reward_function.path is not None:
            # directly use user-customized reward function
            return await self.reward_loop.run_single(data)
        else:
            if self.config.reward_model.enable:
                # we assume the rm is disrm
                # genrm must set custom_reward_function
                return await self.compute_score_disrm(data)
            else:
                return await self.reward_loop.run_single(data)

    # For now, only support DataProto-less inputs for DisRM.
    if getattr(self.config, "custom_reward_function", None) is not None and self.config.custom_reward_function.path:
        raise NotImplementedError(
            "RewardLoopWorker currently supports non-DataProto inputs only in the DisRM path. "
            "When custom_reward_function is configured, you must pass DataProto."
        )
    if not self.config.reward_model.enable:
        raise NotImplementedError(
            "RewardLoopWorker only supports non-DataProto inputs in DisRM mode. "
            "Set reward_model.enable=True (and do not use custom_reward_function), or pass DataProto."
        )

    return await self.compute_score_disrm(input_data)

async def _post_request(self, payload: dict, endpoint: str, max_retries: int = 16):
    url = f"http://{self.reward_router_address}/{endpoint}"
    last_exception = None
    for attempt in range(max_retries):
        try:
            # It's safer to have a timeout instead of None, which can hang indefinitely.
            timeout = aiohttp.ClientTimeout(total=None)
            async with aiohttp.ClientSession(timeout=timeout) as session:
                async with session.post(url, json=payload) as resp:
                    resp.raise_for_status()
                    return await resp.json()
        except aiohttp.ClientResponseError as e:
            # Do not retry on 4xx client errors, but retry on 5xx server errors.
            if 400 <= e.status < 500:
                logger.error(f"Request to {url} failed with client error HTTP {e.status}: {e}. Not retrying.")
                raise
            last_exception = e
            logger.warning(
                f"[Attempt {attempt + 1}/{max_retries}] Request to {url} failed with HTTP {e.status}: {e}. "
                "Retrying..."
            )
        except (asyncio.TimeoutError, aiohttp.ClientConnectorError) as e:
            last_exception = e
            logger.warning(f"[Attempt {attempt + 1}/{max_retries}] Request to {url} failed: {e}. Retrying...")
        except Exception as e:
            last_exception = e
            logger.warning(
                f"[Attempt {attempt + 1}/{max_retries}] Request to {url} failed with unexpected error: {e}. "
                "Retrying..."
            )

        if attempt < max_retries - 1:
            # Using exponential backoff is generally better than a fixed sleep.
            backoff_seconds = 2**attempt
            await asyncio.sleep(min(backoff_seconds, 30))

    logger.error(f"Max retries ({max_retries}) reached for request to {url}.")
    if last_exception:
        raise last_exception

async def _preprocess_reward_inputs(self, data: DataProto) -> str:
    assert len(data) == 1, "RewardLoopWorker only support single data item"
    data_item = data[0]
    assert "raw_prompt" in data_item.non_tensor_batch

    # extract raw prompt
    chat: list = list(data_item.non_tensor_batch["raw_prompt"])

    # extract response
    response_ids = data_item.batch["responses"]
    response_length = response_ids.shape[-1]
    valid_response_length = data_item.batch["attention_mask"][-response_length:].sum()
    valid_response_ids = response_ids[:valid_response_length]

    # decode
    rollout_response = self.input_tokenizer.decode(valid_response_ids)
    # remove bos and eos
    rollout_response = rollout_response.replace(self.input_tokenizer.eos_token, "")

    chat.append({"role": "assistant", "content": rollout_response})

    rm_prompt = self.reward_model_tokenizer.apply_chat_template(
        chat,
        add_generation_prompt=False,
        tokenize=False,
    )

    # llama tokenizer will add bos token by default
    # will be removed in vllm >= 0.11.2, where we can add "add_special_tokens" = False
    if self.reward_model_tokenizer.bos_token is not None and rm_prompt.startswith(
        self.reward_model_tokenizer.bos_token
    ):
        rm_prompt = rm_prompt[len(self.reward_model_tokenizer.bos_token) :]

    return rm_prompt

async def compute_score_disrm(self, input_data) -> dict:
    # verl-native path.
    if isinstance(input_data, DataProto):
        data = input_data
        disrm_prompt = await self._preprocess_reward_inputs(data)
    else:
        # Build DisRM prompt.
        disrm_prompt: str
        if isinstance(input_data, str):
            # Treat as already-prepared prompt for classifier.
            disrm_prompt = input_data
        elif isinstance(input_data, list):
            if self.reward_model_tokenizer is None:
                raise RuntimeError(
                    "reward_model_tokenizer is not initialized; cannot accept messages input for DisRM."
                )
            disrm_prompt = self.reward_model_tokenizer.apply_chat_template(
                input_data,
                add_generation_prompt=False,
                tokenize=False,
            )

            bos = getattr(self.reward_model_tokenizer, "bos_token", None)
            if bos and isinstance(bos, str) and disrm_prompt.startswith(bos):
                disrm_prompt = disrm_prompt[len(bos) :]
        else:
            raise TypeError(
                f"Unsupported input type for DisRM: {type(input_data)}. "
                "Supported: DataProto | str | messages(list[dict])"
            )

    engine_name = self.config.reward_model.rollout.name
    model_name = self.config.reward_model.model.path
    if engine_name == "vllm":
        # TODO (dyy): the "activation" has been changed to "use_activation" in vllm 0.11.2
        payloads = {
            "model": model_name,
            "input": disrm_prompt,
            "activation": False,
            # "add_special_tokens": False,  # vllm >= 0.11.2
        }
        output = await self._post_request(payloads, "classify")
        rm_score = output["data"][-1]["probs"][-1]
    elif engine_name == "sglang":
        payloads = {
            "model": model_name,
            "input": disrm_prompt,
        }
        output = await self._post_request(payloads, "v1/embeddings")
        rm_score = output["data"][-1]["embedding"][-1]
    else:
        raise NotImplementedError(f"RewardLoopWorker does not support reward engine {engine_name}")

    return {"reward_score": rm_score}

from __future__ import annotations

import os
from dataclasses import dataclass, field
from pathlib import Path
from typing import Any


def _default_data_root() -> str:
    return os.getenv("ALFWORLD_DATA_ROOT", "data/alfworld")


@dataclass
class AlfworldTextworldEnv:
    data_root: str = field(default_factory=_default_data_root)
    max_episode_steps: int = 50
    _env: Any = field(init=False, default=None)
    _current_game_path: Path | None = field(init=False, default=None)

    def _games_root(self) -> Path:
        return Path(self.data_root).expanduser().resolve() / "games"

    def _resolve_game_path(self, game_relative_path: str) -> Path:
        game_path = self._games_root() / game_relative_path
        if not game_path.exists():
            raise FileNotFoundError(
                f"ALFWorld game file not found: {game_path}. Expected runtime assets under {self._games_root()}."
            )
        return game_path

    def _close_env(self) -> None:
        if self._env is not None and hasattr(self._env, "close"):
            self._env.close()
        self._env = None
        self._current_game_path = None

    def _build_env(self, game_path: Path):
        try:
            import textworld
            import textworld.gym
        except ImportError as e:
            raise ImportError(
                "TextWorld runtime is not installed. Please install ALFWorld/TextWorld dependencies first."
            ) from e

        wrappers: list[Any] = []
        try:
            from alfworld.agents.utils.misc import Demangler

            class AlfredDemangler(textworld.core.Wrapper):
                def __init__(self, *args, shuffle: bool = False, **kwargs):
                    super().__init__(*args, **kwargs)
                    self.shuffle = shuffle

                def load(self, *args, **kwargs):
                    super().load(*args, **kwargs)
                    demangler = Demangler(game_infos=self._entity_infos, shuffle=self.shuffle)
                    for info in self._entity_infos.values():
                        info.name = demangler.demangle_alfred_name(info.id)

            wrappers.append(AlfredDemangler(shuffle=False))
        except Exception:
            # Friendly feedback still exists in game.tw-pddl, so demangling is optional.
            pass

        class AlfredInfos(textworld.core.Wrapper):
            def __init__(self, *args, **kwargs):
                super().__init__(*args, **kwargs)
                self._gamefile = None

            def load(self, *args, **kwargs):
                super().load(*args, **kwargs)
                self._gamefile = args[0]

            def reset(self, *args, **kwargs):
                state = super().reset(*args, **kwargs)
                try:
                    state["extra.gamefile"] = self._gamefile
                except Exception:
                    pass
                return state

        wrappers.append(AlfredInfos)

        request_infos = textworld.EnvInfos(
            won=True,
            admissible_commands=True,
            extras=["gamefile"],
        )
        env_id = textworld.gym.register_games(
            [str(game_path)],
            request_infos,
            batch_size=1,
            asynchronous=False,
            max_episode_steps=self.max_episode_steps,
            wrappers=wrappers,
        )
        return textworld.gym.make(env_id)

    def _ensure_env(self, game_path: Path) -> None:
        if self._env is not None and self._current_game_path == game_path:
            return
        self._close_env()
        self._env = self._build_env(game_path)
        self._current_game_path = game_path

    @staticmethod
    def _unwrap_batch_item(value: Any) -> Any:
        if isinstance(value, (list, tuple)) and len(value) == 1:
            return value[0]
        return value

    @staticmethod
    def _batch_info_to_single(info: dict[str, Any] | None) -> dict[str, Any]:
        return {key: AlfworldTextworldEnv._unwrap_batch_item(value) for key, value in dict(info or {}).items()}

    @staticmethod
    def _won_to_success(value: Any) -> bool:
        value = AlfworldTextworldEnv._unwrap_batch_item(value)
        if hasattr(value, "item"):
            try:
                value = value.item()
            except Exception:
                pass
        return bool(float(value))

    def _normalize_reset_output(self, reset_output: Any) -> tuple[Any, dict[str, Any]]:
        if isinstance(reset_output, tuple) and len(reset_output) == 2:
            obs, info = reset_output
            return obs, dict(info or {})
        return reset_output, {}

    def _normalize_step_output(self, step_output: Any) -> tuple[Any, float, bool, dict[str, Any]]:
        if isinstance(step_output, tuple) and len(step_output) == 5:
            obs, reward, terminated, truncated, info = step_output
            reward = self._unwrap_batch_item(reward)
            terminated = self._unwrap_batch_item(terminated)
            truncated = self._unwrap_batch_item(truncated)
            info = self._unwrap_batch_item(info)
            return obs, float(reward), bool(terminated or truncated), dict(info or {})
        if isinstance(step_output, tuple) and len(step_output) == 4:
            obs, reward, done, info = step_output
            reward = self._unwrap_batch_item(reward)
            done = self._unwrap_batch_item(done)
            info = self._unwrap_batch_item(info)
            return obs, float(reward), bool(done), dict(info or {})
        if isinstance(step_output, tuple) and len(step_output) == 3:
            obs, reward, done = step_output
            reward = self._unwrap_batch_item(reward)
            done = self._unwrap_batch_item(done)
            return obs, float(reward), bool(done), {}
        raise RuntimeError(f"Unsupported step() output: {type(step_output)} / {step_output!r}")

    @staticmethod
    def _state_to_observation(state: Any) -> str:
        state = AlfworldTextworldEnv._unwrap_batch_item(state)
        if isinstance(state, dict):
            if "feedback" in state:
                return str(state["feedback"])
            if "observation" in state:
                return str(state["observation"])
        return str(state)

    @staticmethod
    def _state_to_info(state: Any, base_info: dict[str, Any]) -> dict[str, Any]:
        state = AlfworldTextworldEnv._unwrap_batch_item(state)
        info = AlfworldTextworldEnv._batch_info_to_single(base_info)
        if isinstance(state, dict):
            for key in ("won", "admissible_commands", "extra.gamefile"):
                if key in state:
                    info[key] = AlfworldTextworldEnv._unwrap_batch_item(state[key])
        info["success"] = AlfworldTextworldEnv._won_to_success(info.get("won", 0.0))
        return info

    def reset_with_info(self, game_relative_path: str, task_id: str | None = None) -> tuple[str, dict[str, Any]]:
        del task_id  # task_id is carried for logging / debugging; game_relative_path is the runtime selector.
        game_path = self._resolve_game_path(game_relative_path)
        self._ensure_env(game_path)
        raw_state, base_info = self._normalize_reset_output(self._env.reset())
        raw_state = self._unwrap_batch_item(raw_state)
        return self._state_to_observation(raw_state), self._state_to_info(raw_state, base_info)

    def reset(self, game_relative_path: str, task_id: str | None = None) -> str:
        observation, _ = self.reset_with_info(game_relative_path=game_relative_path, task_id=task_id)
        return observation

    def step(self, action_str: str) -> tuple[str, float, bool, dict[str, Any]]:
        if self._env is None:
            raise RuntimeError("Environment not initialized. Call reset() before step().")

        raw_state, reward, done, base_info = self._normalize_step_output(self._env.step([action_str]))
        raw_state = self._unwrap_batch_item(raw_state)
        info = self._state_to_info(raw_state, base_info)
        observation = self._state_to_observation(raw_state)
        return observation, reward, done, info

from __future__ import annotations

from dataclasses import dataclass, field
from typing import Any

from recipes.alfworld.env.alfworld_wrapper import AlfworldTextworldEnv

INVALID_TOOL_CALL_ACTION = "<invalid_tool_call>"


@dataclass
class AlfworldToolExecutor:
    max_episode_steps: int = 50
    _env: AlfworldTextworldEnv = field(init=False)
    _history_actions: list[str] = field(default_factory=list)

    def __post_init__(self) -> None:
        self._env = AlfworldTextworldEnv(max_episode_steps=self.max_episode_steps)

    def reset(self, game_relative_path: str, task_id: str | None = None) -> str:
        self._history_actions.clear()
        return self._env.reset(game_relative_path=game_relative_path, task_id=task_id)

    def reset_with_info(self, game_relative_path: str, task_id: str | None = None) -> tuple[str, dict[str, Any]]:
        self._history_actions.clear()
        return self._env.reset_with_info(game_relative_path=game_relative_path, task_id=task_id)

    def step(self, command: str) -> dict[str, Any]:
        self._history_actions.append(command)
        observation, reward, done, info = self._env.step(command)
        return {
            "observation": str(observation),
            "reward": float(reward),
            "done": bool(done),
            "info": info,
            "history_actions": list(self._history_actions),
        }

