import json, glob, collections

for path in sorted(glob.glob('/workspace/results/baseline63/validation/*.jsonl')):
    step = path.split('/')[-1].split('.')[0]
    per_family = collections.defaultdict(lambda: [0,0])  # success, total
    unknown = collections.defaultdict(int)
    for line in open(path):
        row = json.loads(line)
        # locate task_family & success at any nesting level
        fam = None; succ = None
        def walk(o):
            global fam, succ
            if isinstance(o, dict):
                for k,v in o.items():
                    if fam is None and k == 'task_family' and isinstance(v,str):
                        fam = v
                    if succ is None and k == 'success':
                        succ = bool(v)
                    walk(v)
            elif isinstance(o, list):
                for x in o: walk(x)
        walk(row)
        per_family[fam or '?'][1] += 1
        per_family[fam or '?'][0] += 1 if succ else 0
    print(f'=== step {step} ===')
    for fam in sorted(per_family):
        s,t = per_family[fam]
        print(f'  {fam:28s} {s}/{t} = {100*s/t:.1f}%')
"

